Here is the root cause:
The function `tcf_ife_encode()` in `net/sched/act_ife.c` calls `ife_encode()` without checking for a `NULL` return value. When `ife_encode()` fails (e.g., due to memory allocation or encoding failure), it returns `NULL`, and subsequent use of the return pointer in metadata encoding leads to a null‑pointer dereference.

Here is the patch:

 static int tcf_ife_encode(struct sk_buff *skb, const struct tc_action *a,
 			  struct tcf_result *res, struct tcf_ife_params *p)
 {
 	struct tcf_ife_info *ife = to_ife(a);
 	int action = ife->tcf_action;
 	struct ethhdr *oethh;	/* outer ether header */
 	struct tcf_meta_info *e;
 	/*
 	   OUTERHDR:TOTMETALEN:{TLVHDR:Metadatum:TLVHDR..}:ORIGDATA
 	   where ORIGDATA = original ethernet header ...
 	 */
 	u16 metalen = ife_get_sz(skb, ife);
 	int hdrm = metalen + skb->dev->hard_header_len + IFE_METAHDRLEN;
 	unsigned int skboff = 0;
 	int new_len = skb->len + hdrm;
 	bool exceed_mtu = false;
 	void *ife_meta;
 	int err = 0;

 	if (!skb_at_tc_ingress(skb)) {
 		if (new_len > skb->dev->mtu)
 			exceed_mtu = true;
 	}

 	bstats_update(this_cpu_ptr(ife->common.cpu_bstats), skb);
 	tcf_lastuse_update(&ife->tcf_tm);

 	if (!metalen) {		/* no metadata to send */
 		/* abuse overlimits to count when we allow packet
 		 * with no metadata
 		 */
 		qstats_overlimit_inc(this_cpu_ptr(ife->common.cpu_qstats));
 		return action;
 	}
 	/* could be stupid policy setup or mtu config
 	 * so lets be conservative.. */
 	if ((action == TC_ACT_SHOT) || exceed_mtu) {
+drop:
 		qstats_drop_inc(this_cpu_ptr(ife->common.cpu_qstats));
 		return TC_ACT_SHOT;
 	}

 	if (skb_at_tc_ingress(skb))
 		skb_push(skb, skb->dev->hard_header_len);

 	ife_meta = ife_encode(skb, metalen);
+	if (!ife_meta)
+		goto drop;

 	spin_lock(&ife->tcf_lock);

 	/* XXX: we dont have a clever way of telling encode to
 	 * not repeat some of the computations that are done by
 	 * ops->presence_check...
 	 */
 	list_for_each_entry(e, &ife->metalist, metalist) {
 		if (e->ops->encode) {
 			err = e->ops->encode(skb, (void *)(ife_meta + skboff),
 					     e);
 		}
 		if (err < 0) {
 			/* too corrupt to keep around if overwritten */
 			spin_unlock(&ife->tcf_lock);
-			qstats_drop_inc(this_cpu_ptr(ife->common.cpu_qstats));
-			return TC_ACT_SHOT;
+			goto drop;
 		}
 		skboff += err;
 	}
 	spin_unlock(&ife->tcf_lock);
 	oethh = (struct ethhdr *)skb->data;

 	if (!is_zero_ether_addr(p->eth_src))
 		ether_addr_copy(oethh->h_source, p->eth_src);
 	if (!is_zero_ether_addr(p->eth_dst))
 		ether_addr_copy(oethh->h_dest, p->eth_dst);
 	oethh->h_proto = htons(p->eth_type);

 	if (skb_at_tc_ingress(skb))
 		skb_pull(skb, skb->dev->hard_header_len);

 	return action;
 }



